import java.io.*;import java.nio.file.*;import java.security.*;import java.security.cert.X509Certificate;import java.util.*;import com.android.apksig.ApkSigner;
class SignReview {public static void main(String[] a)throws Exception{char[] pass=Files.readString(Path.of(a[1])).trim().toCharArray();KeyStore k=KeyStore.getInstance("PKCS12");try(InputStream in=Files.newInputStream(Path.of(a[0]))){k.load(in,pass);}String alias="rabochaya-karta-review";List<X509Certificate> chain=new ArrayList<>();for(java.security.cert.Certificate c:k.getCertificateChain(alias))chain.add((X509Certificate)c);var cfg=new ApkSigner.SignerConfig.Builder("RK21",(PrivateKey)k.getKey(alias,pass),chain).build();new ApkSigner.Builder(List.of(cfg)).setInputApk(new File(a[2])).setOutputApk(new File(a[3])).setMinSdkVersion(23).setV1SigningEnabled(true).setV2SigningEnabled(true).setV3SigningEnabled(true).build().sign();try(var out=new RandomAccessFile(a[3],"rw")){out.getFD().sync();}System.out.println("Signed and synced");}}
